    result = extract(doc_text)  # tool-use call, see lesson 4.3
    for _ in range(max_retries):
        errors = validate(result)
        if not errors:
            return result
        if all(e.kind == "absent_in_source" for e in errors):
            return flag_for_review(result, errors)  # no retry
        feedback = (
            "Document:\n" + doc_text +
            "\n\nYour previous extraction:\n" + json.dumps(result) +
            "\n\nValidation errors:\n" +
            "\n".join(e.message for e in errors) +
            "\n\nCorrect only these errors."
