function extractWithRetry(docText: string, maxRetries = 2) {
  let result = extract(docText); // tool-use call, see lesson 4.3
  for (let i = 0; i < maxRetries; i++) {
    const errors = validate(result);
    if (errors.length === 0) {
      return result;
    }
    if (errors.every((e) => e.kind === "absent_in_source")) {
      return flagForReview(result, errors); // no retry
    }
    const feedback =
      "Document:\n" + docText +
      "\n\nYour previous extraction:\n" + JSON.stringify(result) +
      "\n\nValidation errors:\n" +
      errors.map((e) => e.message).join("\n") +
      "\n\nCorrect only these errors.";
    result = extract(feedback);
  }
  return flagForReview(result, validate(result));
}

