const REVIEW_SYSTEM = "You review code you did not write. Report bugs only.";

function review(prompt: string) {
  // fresh messages list: no generator history or reasoning
  return client.messages.create({
    model: MODEL, max_tokens: 4096, system: REVIEW_SYSTEM,
    messages: [{ role: "user", content: prompt }],
  });
}

